const updateCoupon = `-- name: UpdateCoupon :execrows
UPDATE coupon SET code = $2, kind = $3, value = $4, all_plans = $5, for_traffic_pack = $6, min_amount = $7, max_uses = $8,
    max_uses_per_user = $9, starts_at = $10, ends_at = $11, is_disabled = $12, remark = $13, updated_at = now()
WHERE id = $1
`

type UpdateCouponParams struct {
	ID             int64
	Code           string
	Kind           string
	Value          int64
	AllPlans       bool
	ForTrafficPack bool
	MinAmount      int64
	MaxUses        int32
	MaxUsesPerUser int32
	StartsAt       pgtype.Timestamptz
	EndsAt         pgtype.Timestamptz
	IsDisabled     bool
	Remark         string
}

func (q *Queries) UpdateCoupon(ctx context.Context, arg UpdateCouponParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCoupon,
		arg.ID,
		arg.Code,
		arg.Kind,
		arg.Value,
		arg.AllPlans,
		arg.ForTrafficPack,
		arg.MinAmount,
		arg.MaxUses,
		arg.MaxUsesPerUser,
		arg.StartsAt,
		arg.EndsAt,
		arg.IsDisabled,
		arg.Remark,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

